function validateCodeIntegrity(path) {
    const fs = require('fs');
    const content = fs.readFileSync(path, 'utf8');

    // فحص الأقواس المتوازنة
    const stack = [];
    const pairs = { '{': '}', '[': ']', '(': ')' };
    for (let char of content) {
        if (pairs[char]) stack.push(char);
        else if (Object.values(pairs).includes(char)) {
            if (stack.length === 0 || pairs[stack.pop()] !== char) {
                return `خطأ في بناء الجملة: قوس غير متوازن عند الرمز '${char}'`;
            }
        }
    }

    // فحص بسيط لوسوم HTML غير مغلقة (مثال أساسي)
    const unclosedTags = content.match(/<([a-z]+)([^<]+)*(?<!\/)>/gi);
    // هذا مجرد فحص أولي، يمكن تطويره لاحقاً

    return stack.length === 0 ? "الكود سليم" : "خطأ: أقواس غير مغلقة";
}
